'use strict';

// MODULES //

var scales = require( '@stdlib/plot/vega/scale/names' );
var factory = require( './factory.js' );


// MAIN //

/**
* Generalized scale constructor.
*
* @name GeneralizedScale
* @constructor
* @type {Function}
* @param {Options} [options] - constructor options
* @param {number} [options.align=0.5] - alignment of elements within a band scale range
* @param {number} [options.base=10] - base of the logarithm to use when performing logarithmic transforms
* @param {(Collection|Object|Signal)} [options.bins] - bin boundaries over the scale domain
* @param {boolean} [options.clamp=false] - boolean indicating whether to clamp output values to the scale range
* @param {number} [options.constant=1] - constant which determines the slope of the symmetric-log transform around zero
* @param {(Collection|Object|Signal)} [options.domain] - domain of associated data values
* @param {boolean} [options.domainImplicit=false] - boolean indicating if an ordinal domain should be implicitly extended with new values
* @param {number} [options.domainMax] - maximum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMin] - minimum value in the scale domain (overrides the `domain` option)
* @param {number} [options.domainMid] - single mid-point value inserted into a two-element domain
* @param {Collection} [options.domainRaw] - array of raw domain values which overrides the `domain` property
* @param {number} [options.exponent=1] - exponent to use when performing exponential transforms
* @param {(string|Object)} [options.interpolate] - scale range interpolation method
* @param {string} [options.name='scale'] - scale name
* @param {(boolean|number|string|Object|Signal)} [options.nice=false] - scale domain "nicing"
* @param {number} [options.padding=0] - scale domain padding (in pixels)
* @param {number} [options.paddingInner=0] - inner padding (spacing) within each step of a band scale
* @param {number} [options.paddingOuter=0] - outer padding (spacing) at the ends of a band scale
* @param {(Collection|Object|Signal|string)} [options.range] - scale range
* @param {boolean} [options.reverse=false] - boolean indicating whether to reverse the order of the scale range
* @param {boolean} [options.round=false] - boolean indicating whether to round numeric output values to integers
* @param {string} [options.type='linear'] - scale type
* @param {boolean} [options.zero] - boolean indicating whether the scale domain should include zero
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @returns {GeneralizedScale} scale instance
*
* @example
* var scale = new GeneralizedScale();
* // returns <GeneralizedScale>
*/
var GeneralizedScale = factory( scales(), {
	'type': 'linear'
});


// EXPORTS //

module.exports = GeneralizedScale;
